using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_RandomEnemyTarget", menuName = "Data/Battle/Logics/Enemy Action/Random Enemy Target")]
public class EnemyActionLogic_RandomEnemyTarget : EnemyActionLogic
{
	[Header("Enemy Units")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		GameObject gameObject = null;
		gameObject = currentCorruptedAnimals.activeCorruptedAnimals.PickRandom();
		if (actionAmount == EffectsValues.NO_VALUE)
		{
			battleAction.CastTarget(gameObject, source);
		}
		else
		{
			battleAction.CastTargetAmount(gameObject, actionAmount, source);
		}
	}
}
